import subprocess
import sys

chunks = ['']

# Clear accumulator
subprocess.run(['agent-browser', '--session', 'csdn-ldzkkj', 'eval', 'window._art42 = ""; "ok"'], capture_output=True)

for i, chunk in enumerate(chunks):
    js = f'window._art42 += "{chunk}"; "chunk {i+1}/{len(chunks)}"'
    result = subprocess.run(['agent-browser', '--session', 'csdn-ldzkkj', 'eval', js], capture_output=True, text=True)
    print(result.stdout.strip())

print(f'Total chunks: 1')
